<script setup>
import WarehouseScene from '../components/WarehouseScene.vue'
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { state, startStudent, checkRound } from '../state.js'
const router = useRouter(), studentId = ref(state.draft?.studentId || ''), studentName = ref(state.draft?.studentName || ''), error = ref('')
async function start() { error.value = ''; if (!await checkRound()) return; try { startStudent(studentId.value, studentName.value); router.push(`/student/${state.draft.submissionResult ? 'submit' : state.draft.step === 'start' ? 'abc' : state.draft.step}`) } catch (e) { error.value = e.message } }
</script>
<template><div class="start-grid"><section class="intro"><p class="eyebrow">仓储管理 · 课堂实训</p><h1>从库存分类<br>到科学储位规划。</h1><p>{{ state.round?.scenario.description || '某电商仓库商品多、拣货路线长。现在，你来担任仓库管理员。' }}</p><WarehouseScene /><p>根据周转量和品项数累积占比完成 ABC 分类，再核算托盘容量、分配储位，并审核储位分配单。周转量为教学需求权重，不等同于现存箱数。</p><div class="task-strip"><span>01 分类</span><span>02 储位分配</span><span>03 单据审核</span><span>04 提交</span></div><p>分类 {{ state.round?.scenario.scoring.abc }} 分 · 合法性 {{ state.round?.scenario.scoring.placementValidity }} 分 · 效率 {{ state.round?.scenario.scoring.placementEfficiency }} 分 · 审核 {{ state.round?.scenario.scoring.documentReview }} 分 · 反思 {{ state.round?.scenario.scoring.reflection }} 分</p><div class="rule"><strong>岗位任务：仓库管理员 / 单据审核员</strong><p>2排 × 4列 × 3层 × 2位 = 48个独立托盘货位。每位一托盘、一SKU；先核对包装与库存，再检查尺寸、堆高和托盘载荷。</p><p>托盘1200×1000×150mm，最大载货1000kg。进入储位分配页查看各商品外箱、箱数、件/箱和各层容量。</p></div><p class="muted">预计用时 30 分钟</p></section><form class="card start-form" @submit.prevent="start"><h2>开始你的实训</h2><p class="muted">当前轮次：{{ state.round ? '#' + state.round.id.slice(0,6) : '尚未开始' }}</p><label>学号 *<input v-model="studentId" required maxlength="32" pattern="[A-Za-z0-9_-]+" autocomplete="username" placeholder="例如 20260101"></label><label>姓名 *<input v-model="studentName" required autocomplete="name" placeholder="输入你的姓名"></label><p v-if="error" class="error" role="alert">✕ {{ error }}</p><button class="primary" :disabled="!state.round || !!state.error || state.expired">开始实训 →</button><button v-if="!state.round" type="button" @click="checkRound">重新检查</button><p class="muted small">草稿只保存在这台电脑。换电脑或清理浏览器会丢失未提交内容，请不要同时打开多个标签页。</p></form></div></template>
